"""Tabbit's data updater.

Brings a local copy of the exported data up to date with a copy served over HTTP - a
CDN, a bucket, a patch server - so a running program can take new data without being
redeployed. Emitted beside the reader and reads nothing but the manifest, so it knows
nothing about the schema and never has to change when one does.

The manifest is what the exporter already writes next to the data: one entry per file
with its size and MD5. Comparing it with the local copy is the whole of the diff, so a
run downloads what changed and nothing else.

Three properties, because a patcher that fails badly is worse than one that does not
exist:

    Nothing is replaced until everything has arrived and been checked. Files land in a
    staging directory first and the local manifest is written last, so an update killed
    halfway leaves the previous data readable and the next run redoes the difference.

    Every file is checked against the hash the manifest gives for it, so a truncated
    transfer that a proxy reported as success does not reach the cache.

    A transient failure is retried with a doubling backoff, and a permanent one is not.

Reading is somebody else's job. This produces a directory, and the generated tables read
it.

The standard library and nothing else: urllib for the transfer, hashlib for the check.
"""

import hashlib
import json
import os
import shutil
import time
import urllib.error
import urllib.request


class UpdateOptions:
    """What an update is allowed to do. Every value has a working default."""

    __slots__ = ("manifest_file_name", "max_attempts", "retry_delay", "request_timeout",
                 "verify_hash", "log")

    def __init__(self, manifest_file_name="manifest-binary.json", max_attempts=3,
                 retry_delay=0.5, request_timeout=30.0, verify_hash=True, log=None):
        # The binary exporter writes manifest-binary.json; the JSON exporter writes
        # manifest-json.json.
        self.manifest_file_name = manifest_file_name

        # The first attempt is included, so three is two retries.
        self.max_attempts = max_attempts

        # Seconds before the second attempt. Doubled for each attempt after it.
        self.retry_delay = retry_delay

        self.request_timeout = request_timeout
        self.verify_hash = verify_hash
        self.log = log


class UpdateResult:
    """What an update did."""

    __slots__ = ("succeeded", "error", "up_to_date", "downloaded_count",
                 "downloaded_bytes", "deleted_count", "local_path")

    def __init__(self, local_path):
        self.succeeded = False
        self.error = None
        self.up_to_date = False
        self.downloaded_count = 0
        self.downloaded_bytes = 0
        self.deleted_count = 0

        # The directory holding the data. Hand it to the generated tables' read_all. Set
        # even on failure, because the previous data is still there and still readable -
        # which is the point of failing the way this does.
        self.local_path = local_path

    def __repr__(self):
        return ("UpdateResult(succeeded=%r, up_to_date=%r, downloaded_count=%r, "
                "deleted_count=%r, error=%r)"
                % (self.succeeded, self.up_to_date, self.downloaded_count,
                   self.deleted_count, self.error))


class ManifestEntry:
    """One file of the manifest, and the hash to check it by."""

    __slots__ = ("name", "size", "hash")

    def __init__(self, name, size, hash_):
        self.name = name
        self.size = size
        self.hash = hash_


class TransientError(Exception):
    """A failure the same request might survive a moment later."""


def parse_manifest(text):
    """Reads the entries out of a manifest's JSON."""
    manifest = json.loads(text)
    items = manifest.get("Items")

    if not isinstance(items, list):
        raise ValueError("the manifest has no Items array")

    return [ManifestEntry(item.get("Name", ""), int(item.get("Size", 0)), item.get("Hash", ""))
            for item in items if item.get("Name")]


def hash_of(data):
    """The MD5 of some bytes, in the lower-case hex the manifest carries."""
    return hashlib.md5(data).hexdigest()


def update(base_url, cache_directory, options=None):
    """Brings `cache_directory` up to date with the data served under `base_url`.

    Does not raise. Everything that can go wrong here - the network, the disk, a file
    that arrived corrupt - is a condition the caller has to handle rather than a defect,
    and a patcher that raises into a service's startup is one that gets wrapped in a
    bare except that swallows the reason.
    """
    options = options or UpdateOptions()
    result = UpdateResult(cache_directory)

    def log(message):
        if options.log is not None:
            options.log(message)

    try:
        manifest_text = _download(
            _join(base_url, options.manifest_file_name), options, log).decode("utf-8")

        remote = parse_manifest(manifest_text)
        local = _read_local_manifest(os.path.join(cache_directory, options.manifest_file_name))

        by_name = {entry.name: entry for entry in local}

        wanted = []

        for entry in remote:
            previous = by_name.get(entry.name)

            # The file's presence is checked as well as the manifest's word for it: a
            # cache somebody cleaned out by hand would otherwise never be refilled.
            current = (previous is not None
                       and previous.hash == entry.hash
                       and os.path.exists(os.path.join(cache_directory, entry.name)))

            if not current:
                wanted.append(entry)

        served = {entry.name for entry in remote}
        gone = [entry.name for entry in local if entry.name not in served]

        if not wanted and not gone:
            log("tabbit: already up to date.")

            result.succeeded = True
            result.up_to_date = True
            return result

        log("tabbit: %d file(s) to fetch, %d to remove." % (len(wanted), len(gone)))

        # Everything lands here first. Nothing the caller can read is touched until the
        # last file has arrived and been checked.
        staging = os.path.join(cache_directory, ".staging")

        os.makedirs(cache_directory, exist_ok=True)
        shutil.rmtree(staging, ignore_errors=True)
        os.makedirs(staging, exist_ok=True)

        for entry in wanted:
            data = _download(_join(base_url, entry.name), options, log)

            if options.verify_hash and entry.hash:
                actual = hash_of(data)

                if actual.lower() != entry.hash.lower():
                    raise ValueError(
                        "%r arrived with hash %s, and the manifest says %s. "
                        "Nothing was replaced." % (entry.name, actual, entry.hash))

            staged = os.path.join(staging, entry.name)

            os.makedirs(os.path.dirname(staged), exist_ok=True)

            with open(staged, "wb") as handle:
                handle.write(data)

            result.downloaded_bytes += len(data)

        # From here on the update is applied. Nothing below reaches the network.
        for name in gone:
            target = os.path.join(cache_directory, name)

            if os.path.exists(target):
                os.remove(target)

            result.deleted_count += 1

        for entry in wanted:
            target = os.path.join(cache_directory, entry.name)

            os.makedirs(os.path.dirname(target), exist_ok=True)

            if os.path.exists(target):
                os.remove(target)

            os.replace(os.path.join(staging, entry.name), target)
            result.downloaded_count += 1

        # Last, and that ordering is the recovery story: a run killed before this point
        # leaves a manifest describing the data that is still on disk, so the next run
        # fetches the same files again rather than believing it has them.
        with open(os.path.join(cache_directory, options.manifest_file_name), "w",
                  encoding="utf-8") as handle:
            handle.write(manifest_text)

        shutil.rmtree(staging, ignore_errors=True)

        log("tabbit: updated. %d fetched, %d removed."
            % (result.downloaded_count, result.deleted_count))

        result.succeeded = True
        return result
    except Exception as error:  # noqa: BLE001 - the caller gets the reason, not a traceback
        # The previous data is untouched, so the caller can carry on with it.
        result.error = str(error)

        log("tabbit: update failed: %s" % result.error)
        return result


def _download(url, options, log):
    """Fetches one URL, retrying what is worth retrying."""
    delay = options.retry_delay
    attempts = max(1, options.max_attempts)

    for attempt in range(1, attempts + 1):
        try:
            return _fetch(url, options)
        except TransientError as error:
            if attempt >= attempts:
                raise

            log("tabbit: %s Retrying in %.1fs (%d of %d)." % (error, delay, attempt, attempts))

            time.sleep(delay)

            # Doubling rather than a fixed wait: a server refusing because it is
            # overloaded is not helped by every client coming back at the same interval.
            delay *= 2


def _fetch(url, options):
    try:
        with urllib.request.urlopen(url, timeout=options.request_timeout) as response:
            return response.read()
    except urllib.error.HTTPError as error:
        message = "%r answered %d %s." % (url, error.code, error.reason)

        # 408 and 429 are the server asking for another attempt, and 5xx is it failing on
        # its own account. A 404 is an answer: retrying it costs three round trips to hear
        # the same thing.
        if error.code in (408, 429) or 500 <= error.code <= 599:
            raise TransientError(message) from error

        raise ValueError(message) from error
    except (urllib.error.URLError, OSError) as error:
        # The request never got an answer - DNS, a refused connection, a timeout.
        raise TransientError("%r could not be reached: %s." % (url, error)) from error


def _read_local_manifest(filename):
    """Reads the cached manifest.

    A missing or unreadable one is an empty manifest, which makes the next update fetch
    everything - the safe direction to be wrong in.
    """
    try:
        with open(filename, "r", encoding="utf-8") as handle:
            return parse_manifest(handle.read())
    except (OSError, ValueError):
        return []


def _join(base_url, name):
    """Joins a base URL and a file name.

    Not os.path.join, which on Windows produces a backslash and a URL no server will
    answer.
    """
    return base_url.rstrip("/") + "/" + name.replace("\\", "/")
